import { axiosInstance } from './axios';

export interface AgentBuilderGenerateSpecRequest {
  space_id: string;
  requirement: string;
}

export interface AgentBuilderCreateDraftRequest {
  space_id: string;
  audit_id?: string;
  spec: AgentSpec;
  resource_plan?: ResourcePlan;
  icon_uri?: string;
}

export interface AgentBuilderGenerateSpecResponse {
  code: string | number;
  msg: string;
  data?: {
    spec?: AgentSpec;
    resource_plan?: ResourcePlan;
    warnings?: string[];
    audit_id?: string;
  };
}

export interface AgentBuilderCreateDraftResponse {
  code: string | number;
  msg: string;
  data?: {
    agent_id?: string;
    bot_id?: string;
    redirect_url?: string;
    bindings?: ResourceBinding;
  };
}

export interface AgentSpec {
  name: string;
  scene_type?: string;
  description: string;
  goal: string;
  prompt: string;
  onboarding?: AgentOnboarding;
  resource_requirements?: ResourceRequirement[];
  variables?: AgentVariable[];
}

export interface AgentOnboarding {
  prologue: string;
  suggested_questions?: string[];
}

export interface ResourceRequirement {
  type: string;
  name: string;
  intent: string;
  keywords?: string[];
  required?: boolean;
}

export interface AgentVariable {
  key: string;
  description: string;
  default_value?: string;
}

export interface ResourcePlan {
  plugin_candidates?: ResourceCandidate[];
  workflow_candidates?: ResourceCandidate[];
  knowledge_candidates?: ResourceCandidate[];
  missing_resources?: MissingResource[];
  risk_warnings?: RiskWarning[];
}

export interface ResourceCandidate {
  type: string;
  id: string;
  name: string;
  description?: string;
  template_key?: string;
  system_name?: string;
  operation_type?: string;
  placeholder_status?: string;
  plugin_id?: string;
  api_id?: string;
  api_name?: string;
  workflow_id?: string;
  dataset_id?: string;
  score: number;
  selected?: boolean;
  reason?: string;
}

export interface RiskWarning {
  code: string;
  level: string;
  message: string;
  related_resource?: string;
}

export interface MissingResource {
  type: string;
  name: string;
  intent: string;
  suggestion: string;
  keywords?: string[];
}

export interface ResourceBinding {
  plugins?: ResourceCandidate[];
  workflows?: ResourceCandidate[];
  knowledge?: ResourceCandidate[];
}

export interface AgentBuilderRecord {
  id: string;
  user_id: string;
  space_id: string;
  requirement_summary: string;
  scene_type: string;
  agent_spec_json: string;
  resource_plan_json: string;
  risk_warnings_json: string;
  status: string;
  bot_id?: string;
  error_message?: string;
  created_at: number;
  updated_at: number;
}

export interface AgentBuilderRecordsListRequest {
  space_id: string;
  page?: number;
  size?: number;
}

export interface AgentBuilderRecordDetailRequest {
  id: string;
  space_id: string;
}

export interface AgentBuilderRecordsListResponse {
  code: string | number;
  msg: string;
  data?: {
    records?: AgentBuilderRecord[];
    total?: string | number;
  };
}

export interface AgentBuilderRecordDetailResponse {
  code: string | number;
  msg: string;
  data?: {
    record?: AgentBuilderRecord;
  };
}

export const agentBuilderApi = {
  GenerateSpec: (req: AgentBuilderGenerateSpecRequest) =>
    axiosInstance.request<unknown, AgentBuilderGenerateSpecResponse>({
      method: 'POST',
      url: '/api/agent_builder/generate_spec',
      data: req,
      headers: {
        'Agw-Js-Conv': 'str',
      },
    }),
  CreateDraft: (req: AgentBuilderCreateDraftRequest) =>
    axiosInstance.request<unknown, AgentBuilderCreateDraftResponse>({
      method: 'POST',
      url: '/api/agent_builder/create_draft',
      data: req,
      headers: {
        'Agw-Js-Conv': 'str',
      },
    }),
  RecordsList: (req: AgentBuilderRecordsListRequest) =>
    axiosInstance.request<unknown, AgentBuilderRecordsListResponse>({
      method: 'POST',
      url: '/api/agent_builder/records/list',
      data: req,
      headers: {
        'Agw-Js-Conv': 'str',
      },
    }),
  RecordDetail: (req: AgentBuilderRecordDetailRequest) =>
    axiosInstance.request<unknown, AgentBuilderRecordDetailResponse>({
      method: 'POST',
      url: '/api/agent_builder/records/detail',
      data: req,
      headers: {
        'Agw-Js-Conv': 'str',
      },
    }),
};
