import { createBrowserRouter, Navigate } from 'react-router-dom';

import { BaseEnum } from '@coze-arch/web-context';
import { SpaceSubModuleEnum } from '@coze-foundation/space-ui-adapter';
import { GlobalError } from '@coze-foundation/layout';

import { Layout } from '../layout';
import {
  LoginPage,
  DefaultSpaceRedirect,
  SpaceLayout,
  SpaceIdLayout,
  Develop,
  AgentBuilder,
  AgentIDELayout,
  AgentIDE,
  spaceSubMenu,
} from './async-components';

export const router: ReturnType<typeof createBrowserRouter> =
  createBrowserRouter([
    {
      path: '/',
      Component: Layout,
      errorElement: <GlobalError />,
      children: [
        {
          index: true,
          element: <Navigate to="/space" replace />,
        },
        {
          path: 'sign',
          Component: LoginPage,
          errorElement: <GlobalError />,
          loader: () => ({
            hasSider: false,
            requireAuth: false,
          }),
        },
        {
          path: 'space',
          Component: DefaultSpaceRedirect,
          loader: () => ({
            hasSider: false,
            requireAuth: true,
          }),
        },
        {
          path: 'space/:space_id',
          Component: SpaceLayout,
          loader: () => ({
            hasSider: true,
            requireAuth: true,
            subMenu: spaceSubMenu,
            menuKey: BaseEnum.Space,
          }),
          children: [
            {
              index: true,
              element: <Navigate to="develop" replace />,
            },
            {
              Component: SpaceIdLayout,
              children: [
                {
                  path: 'develop',
                  Component: Develop,
                  loader: () => ({
                    subMenuKey: SpaceSubModuleEnum.DEVELOP,
                  }),
                },
                {
                  path: 'agent-builder',
                  Component: AgentBuilder,
                  loader: () => ({
                    subMenuKey: SpaceSubModuleEnum.DEVELOP,
                  }),
                },
                {
                  path: 'bot/:bot_id',
                  Component: AgentIDELayout,
                  children: [
                    {
                      index: true,
                      Component: AgentIDE,
                    },
                  ],
                  loader: () => ({
                    hasSider: false,
                    showMobileTips: true,
                    requireBotEditorInit: true,
                    pageName: 'bot',
                  }),
                },
              ],
            },
          ],
        },
        { path: '*', element: <Navigate to="/space" replace /> },
      ],
    },
  ]);
